#!/usr/bin/env python3
"""Workflow harness for this repo (generated by flatmap-repo-forge).

Claude Code runs this as hooks (see .claude/settings.json). Claude also runs it
directly to move the workflow between steps:

    python3 .claude/hooks/harness.py status
    python3 .claude/hooks/harness.py advance <step> [--result pass|fail] [--phase ID] [--task TEXT] [--note TEXT]
    python3 .claude/hooks/harness.py brain-sync

State lives in .harness/state.json. Only `advance` may change it; the hooks
block direct edits. Allowed steps and transitions are in TRANSITIONS below.

Python 3.8+, standard library only.
"""

from __future__ import annotations

import datetime as _dt
import json
import os
import re
import shlex
import subprocess
import sys
import time
from pathlib import Path

ROOT = Path(os.environ.get("CLAUDE_PROJECT_DIR") or Path(__file__).resolve().parents[2])
HARNESS = ROOT / ".harness"
STATE = HARNESS / "state.json"
CONFIG = HARNESS / "config.json"
LOCAL = HARNESS / "config.local.json"
SESSION = HARNESS / ".session.json"

HARNESS_AGENTS = {"planner", "tester", "builder", "reviewer"}
USER_GATED = {"awaiting_phase_approval", "awaiting_test_plan_approval", "awaiting_test_approval",
              "awaiting_merge", "merged", "idle", "stopped_retry_limit"}
WORKING = {"writing_test_plan", "writing_tests", "building", "testing", "reviewing"}

# from-step -> {to-step: requirement}; requirement: None, "pass", "fail"
TRANSITIONS = {
    "multi-phase": {
        "awaiting_phase_approval": {"writing_test_plan": None},
        "writing_test_plan": {"awaiting_test_plan_approval": None},
        "awaiting_test_plan_approval": {"writing_tests": None, "writing_test_plan": None},
        "writing_tests": {"awaiting_test_approval": None},
        "awaiting_test_approval": {"building": None, "writing_tests": None},
        "building": {"testing": None},
        "testing": {"reviewing": "pass", "building": "fail"},
        "reviewing": {"ready_to_ship": "pass", "building": "fail"},
        "ready_to_ship": {"awaiting_merge": None},
        "awaiting_merge": {"merged": None, "building": "fail"},
        "merged": {"awaiting_phase_approval": None, "building": None, "writing_tests": None},
    },
    "single-pass": {
        "idle": {"writing_test_plan": None, "building": None, "writing_tests": None},
        "writing_test_plan": {"awaiting_test_plan_approval": None},
        "awaiting_test_plan_approval": {"writing_tests": None, "writing_test_plan": None},
        "writing_tests": {"awaiting_test_approval": None},
        "awaiting_test_approval": {"building": None, "writing_tests": None},
        "building": {"reviewing": None},
        "reviewing": {"testing": "pass", "building": "fail"},
        "testing": {"ready_to_ship": "pass", "building": "fail"},
        "ready_to_ship": {"awaiting_merge": None},
        "awaiting_merge": {"merged": None, "building": "fail"},
        "merged": {"idle": None, "writing_test_plan": None, "building": None, "writing_tests": None},
    },
}
ANY_FROM_STOPPED = {"building", "writing_tests", "writing_test_plan", "idle", "awaiting_phase_approval", "ready_to_ship"}

AGENT_FOR_STEP = {
    "writing_test_plan": {"tester"},
    "writing_tests": {"tester"},
    "building": {"builder"},
    "testing": {"tester"},
    "reviewing": {"reviewer"},
    "awaiting_phase_approval": {"planner"},
    "merged": {"planner"},
}

ADV = "python3 .claude/hooks/harness.py advance"


# ---------------------------------------------------------------------------
# io helpers
# ---------------------------------------------------------------------------


def now() -> str:
    return _dt.datetime.now(_dt.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")


def load(path: Path, default=None):
    try:
        return json.loads(path.read_text())
    except Exception:  # noqa: BLE001
        return default


def save(path: Path, obj) -> None:
    tmp = path.with_suffix(".tmp")
    tmp.write_text(json.dumps(obj, indent=2) + "\n")
    tmp.replace(path)


def hook_input() -> dict:
    try:
        data = sys.stdin.read()
        return json.loads(data) if data.strip() else {}
    except Exception:  # noqa: BLE001
        return {}


def block(reason: str) -> None:
    """PreToolUse: exit 2 blocks the tool call and shows the reason to Claude."""
    sys.stderr.write(reason + "\n")
    sys.exit(2)


def emit(obj: dict) -> None:
    print(json.dumps(obj))
    sys.exit(0)


def glob_rx(pattern: str) -> re.Pattern:
    i, out = 0, ""
    while i < len(pattern):
        if pattern.startswith("**/", i):
            out += "(?:.*/)?"; i += 3; continue
        if pattern.startswith("**", i):
            out += ".*"; i += 2; continue
        c = pattern[i]
        out += "[^/]*" if c == "*" else "[^/]" if c == "?" else re.escape(c)
        i += 1
    return re.compile("^" + out + "$")


def rel(path: str) -> str:
    try:
        return Path(path).resolve().relative_to(ROOT.resolve()).as_posix()
    except Exception:  # noqa: BLE001
        return path


def git(*args: str) -> str:
    try:
        return subprocess.run(["git", *args], cwd=ROOT, capture_output=True, text=True, timeout=20).stdout.strip()
    except Exception:  # noqa: BLE001
        return ""


# ---------------------------------------------------------------------------
# status text
# ---------------------------------------------------------------------------


def unit(s: dict) -> str:
    if s["mode"] == "multi-phase":
        return f"Phase {s.get('phase')}"
    return f"Task \"{s.get('task')}\"" if s.get("task") else "The current task"


def next_action(s: dict) -> tuple[str, str]:
    """(short line for the user, instruction for Claude)"""
    step, u = s["step"], unit(s)
    pf = f"harness/phases/{s.get('phase')}.md"
    runs = f"run {s.get('run', 0)} of {s.get('retry_limit')}"
    table = {
        "awaiting_phase_approval": (
            f"{u} is drafted and waiting for your approval.",
            f"Show the user {pf}: objective, scope, non-goals, acceptance criteria. Ask them to approve it or ask for changes "
            f"(use the planner agent for changes). Do nothing else until they approve. On approval: {ADV} writing_test_plan"),
        "idle": (
            "Ready. What's the first task?" if not s.get("completed") else "Ready. What's the next task?",
            f"Ask the user what the task is. When they give it: {ADV} writing_test_plan --task \"<task in a few words>\", "
            f"then use the tester agent to write and explain the test plan."),
        "writing_test_plan": (
            f"{u}: the tester is writing the test plan.",
            f"Use the tester agent to write the test plan (into the phase file's Test plan section, or harness/tasks for single-pass) "
            f"and explain each test in plain words. Then: {ADV} awaiting_test_plan_approval"),
        "awaiting_test_plan_approval": (
            f"{u}: the test plan is waiting for your approval.",
            f"Show the user the test plan and explain each test. Ask them to approve or change it. Do not write tests until they approve. "
            f"Approved: {ADV} writing_tests. Changes: {ADV} writing_test_plan"),
        "writing_tests": (
            f"{u}: the tester is writing the tests.",
            f"Use the tester agent to write the approved tests. They should fail for now. Then: {ADV} awaiting_test_approval"),
        "awaiting_test_approval": (
            f"{u}: the written tests are waiting for your approval.",
            f"Show the user the test files and what each test checks. Ask them to approve or change them. "
            f"Approved: commit the tests (git add + git commit), then {ADV} building. Changes: {ADV} writing_tests"),
        "building": (
            f"{u}: the builder is writing the code ({runs}).",
            f"Use the builder agent. Brief it with the phase/task, the approved tests and, on a rerun, the last failure report. "
            f"Then: {ADV} " + ("testing" if s["mode"] == "multi-phase" else "reviewing")),
        "testing": (
            f"{u}: the tester is running the tests ({runs}).",
            f"Use the tester agent to run `make lint typecheck test build` and record exact commands and results in harness/build-log.md. "
            f"Pass: {ADV} " + ("reviewing" if s["mode"] == "multi-phase" else "ready_to_ship") + f" --result pass. Fail: {ADV} building --result fail --note \"<what failed>\""),
        "reviewing": (
            f"{u}: the reviewer is checking the code ({runs}).",
            f"Use the reviewer agent to check the diff against the phase/task and AGENTS.md, including that approved tests weren't changed. "
            f"Pass: {ADV} " + ("ready_to_ship" if s["mode"] == "multi-phase" else "testing") + f" --result pass. Fail: {ADV} building --result fail --note \"<what failed>\""),
        "ready_to_ship": (
            f"{u} passed tests and review. Run /ship to open a pull request.",
            "Tell the user the work passed and that /ship will make a branch, commit, push and open a PR. Wait for them to run /ship."),
        "awaiting_merge": (
            f"{u}: the pull request is open, waiting for CI and your merge approval.",
            f"Check CI with `gh pr checks`. CI failed: {ADV} building --result fail --note \"CI: <what failed>\". "
            f"CI green: ask the user to approve the merge, run `gh pr merge` (it will ask them), then {ADV} merged"),
        "merged": (
            (f"{u} is merged. Say when you want to start the next phase." if s["mode"] == "multi-phase" else f"{u} is merged. What's the next task?"),
            ("Report what was merged and name the next phase in PLANS.md. Wait for the user to say go. Then use the planner agent to draft it "
             f"and: {ADV} awaiting_phase_approval --phase <NN-name>" if s["mode"] == "multi-phase" else
             f"Ask the user for the next task, then: {ADV} writing_test_plan --task \"<task>\"")),
        "stopped_retry_limit": (
            f"{u}: stopped after {s.get('retry_limit')} failed runs. Your call on what to do next.",
            "Show the user what failed on each run (see history in .harness/state.json and harness/build-log.md). Ask how to proceed. "
            f"Then move to the step they choose, e.g. {ADV} building (resets the run count) or {ADV} writing_tests"),
    }
    return table.get(step, (f"Unknown step '{step}'.", "Ask the user how to proceed."))


# ---------------------------------------------------------------------------
# advance (the only writer of state.json)
# ---------------------------------------------------------------------------


def user_answered_since(s: dict) -> bool:
    """True if the user sent a message after the current step was entered."""
    sess = load(SESSION, {}) or {}
    return float(sess.get("last_user_prompt_ts", 0)) > float(s.get("entered_ts", 0))


def tests_dirty(cfg: dict) -> list[str]:
    globs = [glob_rx(g) for g in cfg.get("test_globs", [])]
    dirty = []
    for line in git("status", "--porcelain").splitlines():
        p = line[3:].strip().split(" -> ")[-1]
        if any(g.match(p) for g in globs):
            dirty.append(p)
    return dirty


def cmd_advance(argv: list[str]) -> None:
    import argparse
    ap = argparse.ArgumentParser(prog="harness.py advance")
    ap.add_argument("to")
    ap.add_argument("--result", choices=["pass", "fail"])
    ap.add_argument("--phase")
    ap.add_argument("--task")
    ap.add_argument("--note")
    ap.add_argument("--pr", help="pull request number (set by /ship)")
    a = ap.parse_args(argv)
    s, cfg = load(STATE), load(CONFIG, {})
    if not s:
        print("No .harness/state.json found."); sys.exit(1)
    frm, to = s["step"], a.to

    def refuse(msg: str) -> None:
        print(f"REFUSED: {frm} -> {to}: {msg}")
        sys.exit(1)

    if frm == "stopped_retry_limit":
        if to not in ANY_FROM_STOPPED:
            refuse(f"from stopped_retry_limit you can go to: {', '.join(sorted(ANY_FROM_STOPPED))}")
        need = None
    else:
        allowed = TRANSITIONS[s["mode"]].get(frm, {})
        if to not in allowed:
            refuse(f"not an allowed next step. Allowed: {', '.join(allowed) or 'none'}")
        need = allowed[to]
    if need and a.result != need:
        refuse(f"needs --result {need}")
    if frm == "awaiting_merge":
        if to == "merged":
            # The merge itself is the user's approval (gh pr merge always asks). Confirm it happened.
            state = ""
            try:
                state = subprocess.run(["gh", "pr", "view"] + ([str(s["pr"])] if s.get("pr") else []) + ["--json", "state", "--jq", ".state"], cwd=ROOT,
                                       capture_output=True, text=True, timeout=30).stdout.strip()
            except Exception:  # noqa: BLE001
                pass
            if state != "MERGED" and not user_answered_since(s):
                refuse("the pull request isn't merged yet (gh pr view says: " + (state or "unknown") + ").")
        # CI failing (to building, --result fail) needs no user answer.
    elif frm in USER_GATED and not user_answered_since(s):
        refuse("this step waits for the user. Ask them and wait for their answer before moving on.")
    if to == "awaiting_phase_approval":
        phase = a.phase or (s.get("phase") if frm != "merged" else None)
        if not phase:
            refuse("--phase <NN-name> is required")
        if not (ROOT / "harness" / "phases" / f"{phase}.md").exists():
            refuse(f"harness/phases/{phase}.md doesn't exist yet; draft it with the planner agent first")
        if frm == "merged":
            s["run"] = 0
        s["phase"] = phase
    if to == "writing_test_plan" and s["mode"] == "single-pass" and frm in ("idle", "merged"):
        if not a.task:
            refuse("--task \"<task>\" is required")
        s["task"] = a.task
        s["run"] = 0
    if to == "building" and frm == "awaiting_test_approval":
        dirty = tests_dirty(cfg)
        if dirty:
            refuse("commit the approved tests first: " + ", ".join(dirty))
    if to == "building" and frm in ("awaiting_test_approval", "idle", "merged", "stopped_retry_limit"):
        s["run"] = 1
        if frm in ("idle", "merged") and s["mode"] == "single-pass" and a.task:
            s["task"] = a.task

    if to == "awaiting_merge":
        if not a.pr:
            refuse("--pr <number> is required (from gh pr create)")
        s["pr"] = a.pr

    s["retry_limit"] = int(cfg.get("retry_limit", s.get("retry_limit", 3)))  # config.json is the source
    if a.result == "fail" and to == "building":
        s["run"] = s.get("run", 1) + 1
        if s["run"] > s["retry_limit"]:
            s["run"] -= 1
            to = "stopped_retry_limit"

    if to == "merged":
        done = s.get("phase") if s["mode"] == "multi-phase" else s.get("task")
        s.setdefault("completed", []).append({"id": done, "merged": now()})

    s["history"] = (s.get("history", []) + [{"from": frm, "to": to, "result": a.result, "note": a.note, "run": s.get("run"), "at": now()}])[-200:]
    s.update({"step": to, "last_result": a.result, "entered": now(), "entered_ts": time.time(), "updated": now()})
    save(STATE, s)
    line, todo = next_action(s)
    print(f"OK: {frm} -> {to}. {line}\nNext: {todo}")
    if to == "merged":
        brain_sync(quiet=True)


# ---------------------------------------------------------------------------
# hooks
# ---------------------------------------------------------------------------


def hook_session_start() -> None:
    hook_input()
    s = load(STATE)
    if not s:
        emit({})
    line, todo = next_action(s)
    brain = brain_sync(quiet=True)
    ctx = (
        "This repo uses the flatmap-repo-forge workflow harness. Read AGENTS.md and harness/WORKFLOW.md.\n"
        f"Mode: {s['mode']}. Current step: {s['step']}.\n"
        f"Status: {line}\n"
        f"Next: {todo}\n"
        "Rules: move between steps only with `python3 .claude/hooks/harness.py advance <step>`; never edit .harness/state.json directly. "
        "Never approve on the user's behalf. Stop at every approval step and wait for the user's answer. "
        "Start your first reply by telling the user the status above in one or two sentences."
    )
    if brain.get("warning"):
        ctx += f"\nCompany brain: {brain['warning']}"
    emit({
        "systemMessage": f"flatmap harness: {line} Say anything (e.g. \"go\") to continue.",
        "hookSpecificOutput": {"hookEventName": "SessionStart", "additionalContext": ctx},
    })


def hook_user_prompt() -> None:
    hook_input()
    sess = load(SESSION, {}) or {}
    sess["last_user_prompt"] = now()
    sess["last_user_prompt_ts"] = time.time()
    try:
        save(SESSION, sess)
    except Exception:  # noqa: BLE001
        pass
    sys.exit(0)


SEGMENT_SPLIT = re.compile(r"&&|\|\||;|\||\n")


def push_targets_main(seg: str) -> str | None:
    try:
        words = shlex.split(seg)
    except ValueError:
        words = seg.split()
    if "git" not in words:
        return None
    i = words.index("git") + 1
    while i < len(words) and words[i].startswith("-"):  # git -C dir / -c k=v
        i += 2 if words[i] in ("-C", "-c") else 1
    if i >= len(words) or words[i] != "push":
        return None
    args = words[i + 1:]
    flags = [w for w in args if w.startswith("-")]
    pos = [w for w in args if not w.startswith("-")]
    if any(f in ("--all", "--mirror") for f in flags):
        return "pushes every branch, including main"
    refspecs = pos[1:] if pos else []
    for r in refspecs:
        dst = r.split(":")[-1].lstrip("+")
        if dst in ("main", "master", "refs/heads/main", "refs/heads/master"):
            return f"refspec '{r}' targets main"
        if dst == "HEAD" and git("branch", "--show-current") in ("main", "master"):
            return "HEAD is main"
    if not refspecs and git("branch", "--show-current") in ("main", "master"):
        return "the current branch is main"
    return None


def hook_pre_bash() -> None:
    data = hook_input()
    cmd = (data.get("tool_input") or {}).get("command", "")
    for seg in SEGMENT_SPLIT.split(cmd):
        why = push_targets_main(seg.strip())
        if why:
            block(f"Blocked by the harness: pushing to main isn't allowed ({why}). "
                  "Work on a branch and use /ship to open a pull request.")
    if "state.json" in cmd and "harness.py" not in cmd and re.search(r">|\btee\b|sed\s+-i|\bmv\b|\bcp\b|\brm\b|python|node|\bjq\b|perl", cmd):
        block("Blocked by the harness: .harness/state.json changes only through `python3 .claude/hooks/harness.py advance <step>`.")
    sys.exit(0)


def hook_pre_agent() -> None:
    data = hook_input()
    ti = data.get("tool_input") or {}
    agent = (ti.get("subagent_type") or ti.get("agent") or "").split(":")[-1]
    if agent not in HARNESS_AGENTS:
        sys.exit(0)
    s = load(STATE)
    if not s:
        sys.exit(0)
    allowed = AGENT_FOR_STEP.get(s["step"], set())
    if agent not in allowed:
        _, todo = next_action(s)
        block(f"Blocked by the harness: the {agent} agent doesn't act during step '{s['step']}'. "
              f"Allowed now: {', '.join(sorted(allowed)) or 'no harness agent (this step waits for the user)'}. Next: {todo}")
    sys.exit(0)


def hook_pre_write() -> None:
    data = hook_input()
    path = (data.get("tool_input") or {}).get("file_path") or (data.get("tool_input") or {}).get("notebook_path") or ""
    if rel(path) == ".harness/state.json":
        block("Blocked by the harness: don't edit .harness/state.json. Use `python3 .claude/hooks/harness.py advance <step>`.")
    sys.exit(0)


def phase_files_affected(s: dict) -> list[str]:
    if s.get("mode") != "multi-phase" or not s.get("phase"):
        return []
    pf = ROOT / "harness" / "phases" / f"{s['phase']}.md"
    if not pf.exists():
        return []
    m = re.search(r"^## Files affected\s*\n(.*?)(?=^## |\Z)", pf.read_text(), re.S | re.M)
    if not m:
        return []
    globs = re.findall(r"^\s*-\s*`?([^`\s(]+)`?", m.group(1), re.M)
    return [g for g in globs if not g.startswith("(")]


def hook_post_edit() -> None:
    data = hook_input()
    path = (data.get("tool_input") or {}).get("file_path") or ""
    if not path:
        sys.exit(0)
    cfg, s = load(CONFIG, {}), load(STATE, {})
    r = rel(path)
    # 1. format the touched file
    if cfg.get("fmt_file") and Path(path).suffix in cfg.get("fmt_exts", []) and not r.startswith((".harness/", ".claude/")):
        try:
            subprocess.run(shlex.split(cfg["fmt_file"].replace("{file}", shlex.quote(path))), cwd=ROOT,
                           capture_output=True, timeout=60)
        except Exception:  # noqa: BLE001
            pass
    # 2. flag edits that break the plan
    notes = []
    step = s.get("step")
    tests = [glob_rx(g) for g in cfg.get("test_globs", [])]
    if step not in ("writing_tests", "writing_test_plan") and any(g.match(r) for g in tests):
        notes.append(f"{r} is a test file and the tests were approved. Revert this change, or record the reason in harness/build-log.md "
                     "and show the user the test change for approval; the reviewer fails unexplained test changes.")
    if step == "building":
        allowed = phase_files_affected(s)
        if allowed and not r.startswith(("harness/", ".harness/")) and not any(glob_rx(g).match(r) for g in allowed):
            notes.append(f"{r} isn't in the phase's 'Files affected' list ({', '.join(allowed)}). Keep to the phase scope, or note why in the build log.")
    if notes:
        emit({"decision": "block", "reason": "Harness check: " + " ".join(notes)})
    sys.exit(0)


def hook_stop() -> None:
    data = hook_input()
    if data.get("stop_hook_active"):
        sys.exit(0)
    s = load(STATE)
    if not s or s["step"] not in WORKING:
        sys.exit(0)
    _, todo = next_action(s)
    emit({"decision": "block",
          "reason": f"The workflow step '{s['step']}' isn't finished. Finish it and move on: {todo} "
                    "If you're blocked, explain what's wrong to the user instead."})


# ---------------------------------------------------------------------------
# company brain (high level only; never code)
# ---------------------------------------------------------------------------


def project_version(cfg: dict) -> str:
    vf = ROOT / cfg.get("version_file", "")
    try:
        if vf.name == "package.json":
            return json.loads(vf.read_text()).get("version", "?")
        if vf.name == "pyproject.toml":
            m = re.search(r'^version\s*=\s*"([^"]+)"', vf.read_text(), re.M)
            if m:
                return m.group(1)
    except Exception:  # noqa: BLE001
        pass
    return git("describe", "--tags", "--abbrev=0") or "unversioned"


def brain_entry_path(brain: Path, slug: str) -> tuple[Path, Path | None]:
    for proj_dir, index in ((brain / "wiki" / "projects", brain / "wiki" / "index.md"),
                            (brain / "projects", brain / "index.md")):
        if proj_dir.is_dir():
            return proj_dir / f"{slug}.md", index if index.exists() else None
    idx = brain / "wiki" / "index.md" if (brain / "wiki" / "index.md").exists() else (brain / "index.md")
    return brain / "projects" / f"{slug}.md", idx if idx.exists() else None


def brain_sync(quiet: bool = False) -> dict:
    local, cfg, s = load(LOCAL), load(CONFIG, {}), load(STATE, {})
    if not local or not local.get("brain_path"):
        return {"ok": True, "skipped": "brain tracking is off"}
    brain = Path(local["brain_path"])
    if not brain.is_dir():
        return {"ok": False, "warning": f"brain folder {brain} not found; tracking skipped"}
    entry, index = brain_entry_path(brain, cfg.get("slug", ROOT.name))
    names = sorted({n for n in git("log", "--format=%an").splitlines() if n})
    milestones = [f"{cfg.get('created', '')[:10]}: repo created (harness v{cfg.get('plugin_version')})"]
    for c in s.get("completed", []):
        label = f"phase {c['id']} merged" if s.get("mode") == "multi-phase" else "task merged"
        milestones.append(f"{c.get('merged', '')[:10]}: {label}")
    if cfg.get("deploy_target", "none") != "none":
        milestones.append(f"deploy target set: {cfg['deploy_target']}")
    host = cfg.get("deploy_target") if cfg.get("deploy_target", "none") != "none" else "not decided"
    text = "\n".join([
        f"# {cfg.get('project_name', ROOT.name)}",
        "",
        "<!-- Maintained by flatmap-repo-forge. High-level only: no code, diffs or file names. -->",
        "",
        f"- **About:** {cfg.get('purpose', '')}",
        f"- **Audience:** {cfg.get('audience', '')}",
        f"- **Repo:** https://github.com/{cfg.get('repo', '')}",
        f"- **Local path:** {local.get('local_path', str(ROOT))}",
        f"- **Version:** {project_version(cfg)}",
        f"- **Contributors:** {', '.join(names) or '(none yet)'}",
        f"- **Tech:** {cfg.get('app_type', '')}; UI: {'yes' if cfg.get('ui') else 'no'}; host: {host}",
        f"- **Workflow:** {cfg.get('mode', '')}",
        "",
        "## Milestones",
        "",
    ] + [f"- {m}" for m in milestones]) + "\n"
    try:
        entry.parent.mkdir(parents=True, exist_ok=True)
        changed = not entry.exists() or entry.read_text() != text
        if changed:
            entry.write_text(text)
        linked = False
        if index is not None:
            link_target = os.path.relpath(entry, index.parent)
            idx_text = index.read_text()
            if link_target not in idx_text:
                index.write_text(idx_text.rstrip("\n") + f"\n- [{cfg.get('project_name')}]({link_target}): {cfg.get('purpose', '')[:100]}\n")
                linked = True
        return {"ok": True, "entry": str(entry), "updated": changed, "index_linked": linked}
    except Exception as e:  # noqa: BLE001
        return {"ok": False, "warning": f"couldn't write the brain entry: {e}"}


# ---------------------------------------------------------------------------


def main() -> None:
    if len(sys.argv) < 2:
        print(__doc__); sys.exit(1)
    sub, rest = sys.argv[1], sys.argv[2:]
    if sub == "advance":
        cmd_advance(rest)
    elif sub == "status":
        s = load(STATE)
        if not s:
            print("No .harness/state.json found."); sys.exit(1)
        line, todo = next_action(s)
        print(json.dumps({"mode": s["mode"], "step": s["step"], "unit": unit(s), "run": s.get("run"),
                          "retry_limit": s.get("retry_limit"), "status": line, "next": todo}, indent=2))
    elif sub == "brain-sync":
        print(json.dumps(brain_sync(), indent=2))
    else:
        fn = {"session-start": hook_session_start, "user-prompt": hook_user_prompt, "pre-bash": hook_pre_bash,
              "pre-agent": hook_pre_agent, "pre-write": hook_pre_write, "post-edit": hook_post_edit,
              "stop": hook_stop}.get(sub)
        if not fn:
            print(f"unknown subcommand: {sub}"); sys.exit(1)
        try:
            fn()
        except SystemExit:
            raise
        except Exception as e:  # noqa: BLE001
            # A broken hook must never wedge the session; report and allow.
            sys.stderr.write(f"harness hook '{sub}' error: {e}\n")
            sys.exit(0)


if __name__ == "__main__":
    main()
